using Microsoft.AspNetCore.Mvc;
using Nafadh_Backend.Services;

namespace Nafadh_Backend.Controllers
{
    [ApiController]
    [Route("api/[controller]")]
    public class BadgeController : ControllerBase
    {
        private readonly IBadgeService _service;
        private readonly IBadgeEvaluationService _evaluationService;

        public BadgeController(IBadgeService service, IBadgeEvaluationService evaluationService)
        {
            _service = service;
            _evaluationService = evaluationService;
        }

        // GET: api/Badge
        // The full fixed catalog (for rendering "earned vs not yet earned").
        [HttpGet]
        public async Task<IActionResult> GetAll()
        {
            var badges = await _service.GetAllBadgesAsync();
