        // points, never from a direct client call in normal operation.
        [HttpPost("evaluate/{traineeId}")]
        public async Task<IActionResult> Evaluate(int traineeId)
        {
            await _evaluationService.EvaluateTraineeAsync(traineeId);
            return Ok(new { message = "Badge evaluation completed." });
        }
    }
